// Hand-written. Not generated by Speakeasy.
//
// Guards the binding between a client and its service.
//
// A client is created under a service and Authlete has no operation that moves
// one. Without a force-new marker on the service_id path parameter, editing it
// plans an in-place update: the apply reaches the API, the API refuses it, and
// the practitioner gets a message about the request body rather than about the
// move they attempted. Recreating the client is what actually has to happen.
//
// The marker lives in .speakeasy/terraform_overlay.yaml, on the serviceId
// parameter of all four client operations. An overlay edit or a generator
// change could drop it, and nothing else would notice: the provider would
// still build, and every test that only creates a client would still pass.
package provider

import (
	"context"
	"testing"

	"github.com/hashicorp/terraform-plugin-framework/resource/schema/planmodifier"
	"github.com/hashicorp/terraform-plugin-framework/tfsdk"
	"github.com/hashicorp/terraform-plugin-framework/types"
	"github.com/hashicorp/terraform-plugin-go/tftypes"
)

// serviceIDPlan runs every plan modifier on client.service_id the way the
// framework does, and reports whether a replacement was planned.
//
// The modifier reads req.State.Raw and req.Plan.Raw to tell create and destroy
// apart from update, so both have to be populated. Only their nullness is
// consulted, not their contents.
func serviceIDPlan(t *testing.T, state, config, plan types.String, creating, destroying bool) bool {
	t.Helper()

	attr, ok := resourceSchema(t, NewClientResource()).Attributes["service_id"]
	if !ok {
		t.Fatal("authlete_client has no service_id attribute")
	}
	withModifiers, ok := attr.(interface {
		StringPlanModifiers() []planmodifier.String
	})
	if !ok {
		t.Fatalf("service_id is %T, which carries no string plan modifiers", attr)
	}

	objType := tftypes.Object{AttributeTypes: map[string]tftypes.Type{"service_id": tftypes.String}}
	raw := func(null bool, v types.String) tftypes.Value {
		if null {
			return tftypes.NewValue(objType, nil)
		}
		return tftypes.NewValue(objType, map[string]tftypes.Value{
			"service_id": tftypes.NewValue(tftypes.String, v.ValueString()),
		})
	}

	req := planmodifier.StringRequest{
		ConfigValue: config,
		PlanValue:   plan,
		StateValue:  state,
		State:       tfsdk.State{Raw: raw(creating, state)},
		Plan:        tfsdk.Plan{Raw: raw(destroying, plan)},
	}
	resp := &planmodifier.StringResponse{PlanValue: req.PlanValue}
	for _, m := range withModifiers.StringPlanModifiers() {
		m.PlanModifyString(context.Background(), req, resp)
	}
	return resp.RequiresReplace
}

func TestMovingAClientBetweenServicesRecreatesIt(t *testing.T) {
	from, to := types.StringValue("2000000001"), types.StringValue("2000000002")

	if !serviceIDPlan(t, from, to, to, false, false) {
		t.Error("changing service_id does not plan a replacement.\n\n" +
			"Authlete cannot move a client between services, so this plans an " +
			"in-place update that the API refuses at apply time, and the error " +
			"describes the request rather than the move.\n\n" +
			"Restore `x-speakeasy-param-force-new: true` on the serviceId " +
			"parameter of the client operations in " +
			".speakeasy/terraform_overlay.yaml and regenerate.")
	}
}

// The converse, and the more expensive failure of the two. A replacement
// proposed when service_id has not moved would destroy a working client on an
// unrelated edit.
func TestAnUnchangedServiceIDPlansNoReplacement(t *testing.T) {
	same := types.StringValue("2000000001")

	if serviceIDPlan(t, same, same, same, false, false) {
		t.Error("an unchanged service_id plans a replacement, so every edit to a " +
			"client would destroy and recreate it")
	}
}

// Create and destroy must both stand the rule down. This is the shape that
// made organizationId's equivalent destructive: on the first plan after an
// import, an attribute absent from state read as a change and proposed
// replacing the resource. service_id is set by ImportState and is Required, so
// it cannot repeat that, and these assert it stays so.
func TestCreateAndDestroyPlanNoReplacement(t *testing.T) {
	id := types.StringValue("2000000001")

	if serviceIDPlan(t, types.StringNull(), id, id, true, false) {
		t.Error("creating a client plans a replacement")
	}
	if serviceIDPlan(t, id, id, types.StringNull(), false, true) {
		t.Error("destroying a client plans a replacement")
	}
}
